    recognition: "A modern, tree-shaded grid of boutique bars, third-wave cafes and rooftop lounges with hip signage and a mixed local/expat/student crowd — a world away from the moat and temples.",
    localName: "ถนนนิมมานเหมินท์ · Thanon Nimmanhaemin",
    categories: ["nightlife", "bars", "cocktail", "live-music", "cafe-bar"],
    budgetTier: "mid",
    kidFriendly: false,
    blurb: "The leafy, design-led district west of the old city where cocktail bars, craft-beer spots, rooftop lounges and live-music cafes cluster along Nimman and its numbered sois (Soi 9, Soi 11) and the Think Park / One Nimman corners.",
    whyItFits: "Chiang Mai's most reliable modern going-out area — a whole neighbourhood of bars rather than a single venue — popular with students, digital nomads and locals, and a relaxed alternative to the beer-bar strips.",
    priceRange: { low: 300, typical: 800, high: 1500, currency: "THB", note: "Craft cocktails 180-320 THB, local beer 90-160 THB, craft beer 200+ THB. Cheaper the further off the main road you go." },
    hours: "Bars roughly 18:00-00:00, some to 01:00; quieter and earlier-closing than Bangkok.",
    tips: ["Explore the sois (especially Soi 9 and Soi 11) — the best small bars are tucked off the main road.", "Pair it with the nearby One Nimman plaza for early-evening food before drinks.", "Weeknights are mellow; Fri-Sat the live-music bars fill up."],
    scamWarnings: ["Generally low-hassle, but still keep an eye on your drink.", "Confirm whether live-music venues add a cover or minimum spend before sitting down.", "Ride-hail (Grab/Bolt) or agree the tuk-tuk fare before riding back."],
    mapQuery: "Nimmanhaemin Road bar scene Chiang Mai",
